package com.mealmate.availability.web;
import com.mealmate.availability.service.AvailabilityService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import static com.mealmate.availability.web.AvailabilityDtos.*;
@RestController @RequestMapping("/availability") public class AvailabilityController {private final AvailabilityService s; public AvailabilityController(AvailabilityService s){this.s=s;} @GetMapping("/menu-items/{id}") public AvailabilityResponse get(@PathVariable UUID id){return s.get(id);} @PutMapping("/menu-items/{id}") public AvailabilityResponse set(@PathVariable UUID id,@Valid @RequestBody AvailabilityRequest x){return s.set(id,x);} @PostMapping("/reservations") public ResponseEntity<ReservationResponse> reserve(@Valid @RequestBody ReservationRequest x){return ResponseEntity.status(HttpStatus.CREATED).body(s.reserve(x));} @DeleteMapping("/reservations/{orderId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void release(@PathVariable UUID orderId){s.release(orderId);}}
